-- CME futures for the Futures Challenge. contract_size = dollars per 1.00 of price (matches trading-engine INSTRUMENTS).
-- Commission is per contract, charged round-turn on close: US$4 full-size, US$1 micro.
begin;
alter table public.symbol_specs drop constraint if exists symbol_specs_asset_class_check;
alter table public.symbol_specs add constraint symbol_specs_asset_class_check check (asset_class = any (array['forex','metal','index','crypto','future']));
commit;
